/// A view allows us to pre-define a query to run on a dataset
#[derive(Default, PartialEq, Debug, Clone)]
pub struct View {
    /// The source query to run
    query: Query,
}

impl View {
    pub fn serialize_to<'a>(&self, builder: &mut flatbuffers::FlatBufferBuilder<'a>) -> flatbuffers::WIPOffset<FbsView<'a>> {
        use crate::types::generated::view_generated::ViewBuilder as FbsViewBuilder;

        let query_offset = self.query.serialize_to(builder);

        let mut bldr = FbsViewBuilder::new(builder);
        bldr.add_query(query_offset);
        bldr.finish()
    }
}

impl From<FbsView<'_>> for View {
    fn from(fbs: FbsView<'_>) -> Self {
        let query = Query::from(fbs.query());
        Self {
            query,
        }
    }
}

impl TryFrom<&[u8]> for View {
    type Error = flatbuffers::InvalidFlatbuffer;
    fn try_from(bytes: &[u8]) -> Result<Self, Self::Error> {
        let fbs = flatbuffers::size_prefixed_root::<FbsView>(bytes)?;
        Ok(Self::from(fbs))
    }
}

impl From<View> for Vec<u8> {
    fn from(obj: View) -> Self {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = obj.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }
}

